// Send an invisible straight line through a tile map and report the first wall it hits.
// raycasting: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width, height, ox, oy, dx, dy, limit, ...grid]
// Output: [cell_x, cell_y, ray_parameter] or []
// Grid DDA; Y wins corner ties. Direction need not have unit length. Solid tiles are nonzero.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

// Count how many numbers are in this list.
function port_length(a: number[]): number { return a.length; }
// Read one number at a zero-based position; stop if that position does not exist.
function port_get(a: number[], i: number): number { if (!Number.isInteger(i) || i < 0 || i >= a.length) throw new RangeError("index"); return a[i]; }
// Round down to a whole number; minus 0.1 becomes minus 1.
function port_floor_num(a: number): number { return Math.floor(a); }
// Remove a negative sign so a distance or size is not negative.
function port_abs_num(a: number): number { return Math.abs(a); }

// 1. Start the line at a position and choose its direction.
// 2. Calculate which tile edge the line will cross next.
// 3. Move into that next tile and check whether it is a wall.
// 4. Stop at a wall, the map edge, or the step limit. The returned time-like number tells how
// far along the line the hit occurred.
export function compute(data: number[]): number[] {
    let w: number = 0;
    let h: number = 0;
    let ox: number = 0;
    let oy: number = 0;
    let dx: number = 0;
    let dy: number = 0;
    let limit: number = 0;
    let x: number = 0;
    let y: number = 0;
    let sx: number = 0;
    let sy: number = 0;
    let tx: number = 0;
    let ty: number = 0;
    let stepx: number = 0;
    let stepy: number = 0;
    let t: number = 0;
    let i: number = 0;
    w = port_get(data, 0);
    h = port_get(data, 1);
    ox = port_get(data, 2);
    oy = port_get(data, 3);
    dx = port_get(data, 4);
    dy = port_get(data, 5);
    limit = port_get(data, 6);
    if (((w < 1) || (h < 1) || (port_length(data) != (7 + (w * h))) || ((dx == 0) && (dy == 0)))) {
        return [];
    }
    x = port_floor_num(ox);
    y = port_floor_num(oy);
    sx = -(1);
    sy = -(1);
    if ((dx > 0)) {
        sx = 1;
    }
    if ((dy > 0)) {
        sy = 1;
    }
    // A large sentinel replaces infinity for this bounded educational ray.
    tx = 1e+30;
    ty = 1e+30;
    stepx = 1e+30;
    stepy = 1e+30;
    if ((dx != 0)) {
        tx = ((x - ox) / dx);
        if ((dx > 0)) {
            tx = (((x + 1) - ox) / dx);
        }
        stepx = port_abs_num((1 / dx));
    }
    if ((dy != 0)) {
        ty = ((y - oy) / dy);
        if ((dy > 0)) {
            ty = (((y + 1) - oy) / dy);
        }
        stepy = port_abs_num((1 / dy));
    }
    t = 0;
    i = 0;
    while ((i < limit)) {
        if (((x < 0) || (x >= w) || (y < 0) || (y >= h))) {
            return [];
        }
        if ((port_get(data, ((7 + (y * w)) + x)) != 0)) {
            return [x, y, t];
        }
        if ((tx < ty)) {
            t = tx;
            tx += stepx;
            x += sx;
        } else {
            t = ty;
            ty += stepy;
            y += sy;
        }
        i += 1;
    }
    return [];
}
